// ../es-samples/samples/es2026/regexp-escape.js
function demoRegExpEscape() {
  const userInput = "Hello [World] (test)* +$?^|\\";
  if (typeof RegExp.escape === "function") {
    const escaped2 = RegExp.escape(userInput);
    const regex = new RegExp(escaped2);
    return { escaped: escaped2, matches: regex.test(userInput) };
  }
  const fallbackEscape = (str) => str.replace(/[\\^$*+?.()|[\]{}]/g, "\\$&");
  const escaped = fallbackEscape(userInput);
  return { escaped, matches: new RegExp(escaped).test(userInput), isPolyfill: true };
}

